//! Runs the generated credits migrations against SQLite and checks the store works on top of them.
#![cfg(feature = "credits-seaorm")]

use sea_orm_migration::prelude::*;
use sea_orm_migration::sea_orm::{Database, DatabaseConnection};
use tideway::credits::{
    CreditHistoryQuery, CreditSource, CreditStore, CreditTransactionKind, GrantCredits,
    RevocationAmount, RevokeCredits, SeaOrmCreditStore,
};

// The templates are application code generated by the CLI; keep their formatting as shipped.
#[rustfmt::skip]
#[path = "../../tideway-cli/templates/backend/migrations/m013_create_credit_ledger.hbs"]
mod m013_create_credit_ledger;
#[rustfmt::skip]
#[path = "../../tideway-cli/templates/backend/migrations/m015_add_credit_revocation.hbs"]
mod m015_add_credit_revocation;

struct Migrator;

#[async_trait::async_trait]
impl MigratorTrait for Migrator {
    fn migrations() -> Vec<Box<dyn MigrationTrait>> {
        vec![
            Box::new(m013_create_credit_ledger::Migration),
            Box::new(m015_add_credit_revocation::Migration),
        ]
    }
}

#[tokio::test]
async fn revocation_migration_upgrades_an_existing_sqlite_ledger() {
    let db = Database::connect("sqlite::memory:").await.unwrap();
    assert_revocation_upgrade(db).await;
}

#[tokio::test]
#[ignore = "requires PostgreSQL via TEST_DATABASE_URL"]
async fn revocation_migration_upgrades_an_existing_postgres_ledger() {
    let test_db = tideway::testing::TestDb::new_postgres()
        .await
        .expect("create PostgreSQL test database");
    assert_revocation_upgrade(test_db.connection()).await;
}

async fn assert_revocation_upgrade(db: DatabaseConnection) {
    let store = SeaOrmCreditStore::new(db.clone());
    let manager = SchemaManager::new(&db);

    // An app that already ran the original ledger migration and recorded a grant.
    Migrator::up(&db, Some(1)).await.unwrap();
    db.execute_unprepared(
        r#"INSERT INTO credit_transactions
           (id, account_id, credit_type, kind, amount, idempotency_key, created_at, metadata)
           VALUES ('tx-legacy', 'org-1', 'sms', 'grant', 5, 'legacy', 1, '{}')"#,
    )
    .await
    .unwrap();
    assert!(
        db.execute_unprepared(
            r#"INSERT INTO credit_transactions
               (id, account_id, credit_type, kind, amount, idempotency_key, created_at, metadata)
               VALUES ('tx-revoke', 'org-1', 'sms', 'revoke', 5, 'r', 1, '{}')"#,
        )
        .await
        .is_err(),
        "the original ledger rejects revoke entries"
    );

    Migrator::up(&db, None).await.unwrap();
    // Rerunning the upgrade is harmless.
    m015_add_credit_revocation::Migration
        .up(&manager)
        .await
        .unwrap();
    assert!(
        manager
            .has_index("credit_transactions", "idx_credit_transactions_history")
            .await
            .unwrap()
    );

    store
        .grant(
            &GrantCredits {
                account_id: "org-1".into(),
                credit_type: "sms".into(),
                amount: 100,
                source: CreditSource::Purchased,
                expires_at: None,
                idempotency_key: "stripe-payment-intent:pi_1".into(),
                metadata: serde_json::json!({}),
            },
            10,
        )
        .await
        .unwrap();
    let revocation = store
        .revoke(
            &RevokeCredits {
                grant_idempotency_key: "stripe-payment-intent:pi_1".into(),
                amount: RevocationAmount::ALL,
                idempotency_key: "stripe-event:evt_1".into(),
                metadata: serde_json::json!({}),
            },
            20,
        )
        .await
        .unwrap()
        .unwrap();
    assert_eq!(revocation.revoked_amount, 100);
    assert_eq!(
        store.balance("org-1", "sms", 20).await.unwrap().available,
        0
    );

    let history = store
        .history("org-1", "sms", CreditHistoryQuery::default())
        .await
        .unwrap();
    assert!(history.iter().any(|entry| entry.id == "tx-legacy"));
    assert!(
        history
            .iter()
            .any(|entry| entry.kind == CreditTransactionKind::Revoke)
    );
}
